   1→import { showToast } from "~/utils/toast";
   2→import { useState, useCallback, useEffect } from "react";
   3→import {
   4→  data,
   5→  redirect,
   6→  type ActionFunctionArgs,
   7→  type HeadersFunction,
   8→  type LoaderFunctionArgs,
   9→} from "react-router";
  10→import { useLoaderData, useActionData, useNavigate, useSubmit } from "react-router";
  11→import {
  12→  Page,
  13→  Layout,
  14→  Card,
  15→  Text,
  16→  InlineStack,
  17→  BlockStack,
  18→  Badge,
  19→  Button,
  20→  Box,
  21→  Divider,
  22→  TextField,
  23→  Select,
  24→  Tabs,
  25→  Tag,
  26→  Checkbox,
  27→  ButtonGroup,
  28→  Modal,
  29→  SkeletonPage,
  30→  SkeletonBodyText,
  31→} from "@shopify/polaris";
  32→import { authenticate } from "../shopify.server";
  33→import { boundary } from "@shopify/shopify-app-react-router/server";
  34→import db from "../db.server";
  35→
  36→// --- Types ---
  37→
  38→interface AnswerOption {
  39→  id: string;
  40→  label: string;
  41→  score: number;
  42→  productTags: string[];
  43→  position: number;
  44→}
  45→
  46→interface Question {
  47→  id: string;
  48→  title: string;
  49→  type: string;
  50→  required: boolean;
  51→  position: number;
  52→  options: AnswerOption[];
  53→}
  54→
  55→interface DesignSettings {
  56→  quizTitle: string;
  57→  description: string;
  58→  buttonColor: string;
  59→  buttonText: string;
  60→  resultsHeading: string;
  61→  showProgressBar: boolean;
  62→}
  63→
  64→interface LoaderData {
  65→  quiz: {
  66→    id: string;
  67→    title: string;
  68→    description: string | null;
  69→    slug: string;
  70→    status: string;
  71→    settings: string;
  72→    styling: string;
  73→  };
  74→  questions: Question[];
  75→  designSettings: DesignSettings;
  76→}
  77→
  78→// --- Helpers ---
  79→
  80→const questionTypeOptions = [
  81→  { label: "Single choice", value: "single" },
  82→  { label: "Multiple choice", value: "multiple" },
  83→  { label: "Image choice", value: "image-choice" },
  84→  { label: "Dropdown", value: "dropdown" },
  85→  { label: "Slider", value: "slider" },
  86→  { label: "Email capture", value: "email" },
  87→  { label: "Text input", value: "text-input" },
  88→  { label: "Rating", value: "rating" },
  89→];
  90→
  91→function parseSafe<T>(str: string, fallback: T): T {
  92→  try {
  93→    return JSON.parse(str) as T;
  94→  } catch {
  95→    return fallback;
  96→  }
  97→}
  98→
  99→// --- Loader ---
 100→
 101→export const loader = async ({ request, params }: LoaderFunctionArgs) => {
 102→  const { session } = await authenticate.admin(request);
 103→  const quizId = params.id;
 104→
 105→  if (!quizId) {
 106→    throw data({ error: "Missing quiz ID" }, { status: 400 });
 107→  }
 108→
 109→  try {
 110→    const quiz = await db.quiz.findFirst({
 111→      where: { id: quizId, shop: session.shop },
 112→      include: {
 113→        questions: {
 114→          include: { answers: { orderBy: { position: "asc" } } },
 115→          orderBy: { position: "asc" },
 116→        },
 117→      },
 118→    });
 119→
 120→    if (!quiz) {
 121→      throw data({ error: "Quiz not found" }, { status: 404 });
 122→    }
 123→
 124→    const stylingObj = parseSafe<{
 125→      buttonColor?: string;
 126→      buttonText?: string;
 127→      resultsHeading?: string;
 128→      showProgressBar?: boolean;
 129→    }>(quiz.styling, {});
 130→
 131→    const designSettings: DesignSettings = {
 132→      quizTitle: quiz.title,
 133→      description: quiz.description ?? "",
 134→      buttonColor: stylingObj.buttonColor ?? "#5C6AC4",
 135→      buttonText: stylingObj.buttonText ?? "Next",
 136→      resultsHeading: stylingObj.resultsHeading ?? "Your Results",
 137→      showProgressBar: stylingObj.showProgressBar ?? true,
 138→    };
 139→
 140→    const questions: Question[] = quiz.questions.map((q) => ({
 141→      id: q.id,
 142→      title: q.title,
 143→      type: q.type,
 144→      required: q.required,
 145→      position: q.position,
 146→      options: q.answers.map((a) => ({
 147→        id: a.id,
 148→        label: a.text,
 149→        score: a.score,
 150→        productTags: parseSafe(a.productTags, [] as string[]),
 151→        position: a.position,
 152→      })),
 153→    }));
 154→
 155→    return {
 156→      quiz: {
 157→        id: quiz.id,
 158→        title: quiz.title,
 159→        description: quiz.description,
 160→        slug: quiz.slug,
 161→        status: quiz.status,
 162→        settings: quiz.settings,
 163→        styling: quiz.styling,
 164→      },
 165→      questions,
 166→      designSettings,
 167→    } as LoaderData;
 168→  } catch (error) {
 169→    if (error instanceof Response) throw error;
 170→    throw data({ error: "Failed to load quiz" }, { status: 500 });
 171→  }
 172→};
 173→
 174→// --- Action ---
 175→
 176→export const action = async ({ request, params }: ActionFunctionArgs) => {
 177→  const { session } = await authenticate.admin(request);
 178→  const quizId = params.id!;
 179→  const formData = await request.formData();
 180→  const intent = String(formData.get("intent") ?? "");
 181→
 182→  try {
 183→    // Verify ownership before any mutation
 184→    const quiz = await db.quiz.findFirst({
 185→      where: { id: quizId, shop: session.shop },
 186→    });
 187→    if (!quiz) {
 188→      return data({ error: "Quiz not found" }, { status: 404 });
 189→    }
 190→
 191→    switch (intent) {
 192→      case "save-design": {
 193→        const title = String(formData.get("title") ?? "").trim();
 194→        const description =
 195→          String(formData.get("description") ?? "").trim() || null;
 196→        const styling = String(formData.get("styling") ?? "{}");
 197→        if (!title) {
 198→          return data({ error: "Title is required" }, { status: 400 });
 199→        }
 200→        await db.quiz.update({
 201→          where: { id: quizId },
 202→          data: { title, description, styling, updatedAt: new Date() },
 203→        });
 204→        return { success: true, message: "Design saved!" };
 205→      }
 206→
 207→      case "publish": {
 208→        await db.quiz.update({
 209→          where: { id: quizId },
 210→          data: {
 211→            status: "active",
 212→            publishedAt: quiz.publishedAt ?? new Date(),
 213→          },
 214→        });
 215→        return {
 216→          success: true,
 217→          message: "Quiz published! It's now live on your storefront.",
 218→        };
 219→      }
 220→
 221→      case "unpublish": {
 222→        await db.quiz.update({
 223→          where: { id: quizId },
 224→          data: { status: "draft" },
 225→        });
 226→        return { success: true, message: "Quiz unpublished." };
 227→      }
 228→
 229→      case "delete": {
 230→        await db.quiz.delete({ where: { id: quizId } });
 231→        return redirect("/app/quizzes");
 232→      }
 233→
 234→      case "save-questions": {
 235→        const questionsJson = String(formData.get("questions") ?? "[]");
 236→        let questions: Array<{
 237→          id?: string;
 238→          title: string;
 239→          type: string;
 240→          required: boolean;
 241→          position: number;
 242→          options: Array<{
 243→            id?: string;
 244→            label: string;
 245→            score: number;
 246→            productTags: string[];
 247→            position: number;
 248→          }>;
 249→        }>;
 250→
 251→        try {
 252→          questions = JSON.parse(questionsJson);
 253→        } catch {
 254→          return data({ error: "Invalid questions data" }, { status: 400 });
 255→        }
 256→
 257→        // Delete all existing questions (cascade deletes answers)
 258→        await db.question.deleteMany({ where: { quizId } });
 259→
 260→        // Re-create all questions with their answers
 261→        for (const q of questions) {
 262→          await db.question.create({
 263→            data: {
 264→              quizId,
 265→              title: q.title,
 266→              type: q.type,
 267→              required: q.required,
 268→              position: q.position,
 269→              answers: {
 270→                create: q.options.map((a) => ({
 271→                  text: a.label,
 272→                  score: a.score,
 273→                  productTags: JSON.stringify(a.productTags),
 274→                  position: a.position,
 275→                })),
 276→              },
 277→            },
 278→          });
 279→        }
 280→        return { success: true, message: "Questions saved!" };
 281→      }
 282→
 283→      default:
 284→        return data({ error: "Unknown action" }, { status: 400 });
 285→    }
 286→  } catch (error) {
 287→    if (error instanceof Response) throw error;
 288→    console.error(`Quiz action "${intent}" failed:`, error);
 289→    return data(
 290→      { error: "Action failed. Please try again." },
 291→      { status: 500 },
 292→    );
 293→  }
 294→};
