 696→export default function QuizBuilder() {
 697→  const loaderData = useLoaderData<typeof loader>();
 698→  const actionData = useActionData<typeof action>();
 699→  const navigate = useNavigate();
 700→  const submit = useSubmit();
 701→
 702→  const { quiz, questions: initialQuestions, designSettings: initialDesign } =
 703→    loaderData;
 704→
 705→  const [questions, setQuestions] = useState<Question[]>(initialQuestions);
 706→  const [selectedQuestionIndex, setSelectedQuestionIndex] = useState(0);
 707→  const [design, setDesign] = useState<DesignSettings>(initialDesign);
 708→  const [selectedTab, setSelectedTab] = useState(0);
 709→  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
 710→
 711→  const quizId = quiz.id;
 712→
 713→  // Show toast on every action result
 714→  useEffect(() => {
 715→    if (!actionData) return;
 716→    if ("success" in actionData && actionData.success && "message" in actionData) {
 717→      showToast(String(actionData.message), { duration: 3000 });
 718→    } else if ("error" in actionData && actionData.error) {
 719→      showToast(String(actionData.error), {
 720→        duration: 4000,
 721→        isError: true,
 722→      });
 723→    }
 724→  }, [actionData]);
 725→
 726→  const tabs = [
 727→    { id: "questions", content: "Questions", panelID: "questions-panel" },
 728→    { id: "mapping", content: "Product Mapping", panelID: "mapping-panel" },
 729→    { id: "design", content: "Design", panelID: "design-panel" },
 730→  ];
 731→
 732→  const handleTabChange = useCallback((index: number) => {
 733→    setSelectedTab(index);
 734→  }, []);
 735→
 736→  // Save questions tab
